void FloatMatVec(int rows, int cols, const float* matrix, const float* vec,
                 const float* bias, float* output) {
#if defined(CMSIS_NN) && defined(TFLITE_MICRO_CMSIS_NN_F32)
  // MVE-F path: output[1 x rows] = vec[1 x cols] * matrix[rows x cols]^T + bias.
  // arm_nn_mat_mult_nt_t_f32 computes dst[r][c] = bias[c] + dot(lhs_row_r,
  // rhs_row_c); with lhs_rows=1 this is exactly the matrix-vector product.
  // row_address_offset must be > 0 (unused for a single lhs row).
  arm_nn_mat_mult_nt_t_f32(vec, matrix, bias, output,
                           /*lhs_rows=*/1, /*rhs_rows=*/rows, /*rhs_cols=*/cols,
                           /*row_address_offset=*/rows,
                           -FLT_MAX, FLT_MAX);
#else
  for (int i = 0; i < rows; ++i) {
    float sum = bias[i];
    for (int j = 0; j < cols; ++j) {
      sum += vec[j] * matrix[i * cols + j];
    }
    output[i] = sum;
  }
#endif
}

